import axios from 'axios';
import React, { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom';


import { Property } from '../../../types/property';
import { BASE_URL } from '../../../utils/requests';
import {DetailWrapper,Detailgrid} from './styles';

type Props = {
    propertyId : string;
}




const PropertyDetails = ({propertyId}: Props)=>{

    const navigate= useNavigate();

    const [property, setProperty] = useState<Property>();

    useEffect(() =>{
        axios.get(`${BASE_URL}/movies/${propertyId}`)
             .then(Response => {
                 setProperty(Response.data);
             });
    }, [propertyId]);
    return(
        <DetailWrapper>
            <h3>Detail</h3>
            <Detailgrid>
                <div>
                    <h4>Price</h4>
                    <span>valor</span>
                </div>
                <div>
                    <h4>Title</h4>
                    <span>valor</span>
                </div>
                <div>
                    <h4>Title</h4>
                    <span>valor</span>
                </div>
                <div>
                    <h4>Title</h4>
                    <span>valor</span>
                </div>
            </Detailgrid>
        </DetailWrapper>
    )
}

export default PropertyDetails
